import numpy as np
import time
from scipy.optimize import linprog


def _hex_init(n=32):
    # Hexagonal-ish layout of centers in the unit square
    pts = []
    rows = 6
    for j in range(rows):
        y = (j + 0.5) / rows
        cols = 6 if j % 2 == 0 else 5
        for i in range(cols):
            x = (i + 0.5) / cols
            if j % 2 == 1:
                x = (i + 1.0) / (cols + 1)
            pts.append((x, y))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    return np.array(pts, dtype=float)


def _solve_lp(centers):
    n = len(centers)
    # variables: r_0..r_{n-1}
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    # wall constraints: r_i <= x_i, r_i <= 1-x_i, r_i <= y_i, r_i <= 1-y_i
    for i in range(n):
        x, y = centers[i]
        for bound in (x, 1.0 - x, y, 1.0 - y):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(bound)
    # pair constraints: r_i + r_j <= d_ij
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    bounds = [(0, None)] * n
    res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                  bounds=bounds, method='highs')
    if not res.success:
        return None
    return res.x


def _relax(centers, radii, step=0.02, margin=0.002):
    n = len(centers)
    disp = np.zeros_like(centers)
    for i in range(n):
        xi, yi = centers[i]
        ri = radii[i]
        # wall pushes
        for (val, axis, sign) in ((xi, 0, 1.0), (1.0 - xi, 0, -1.0),
                                  (yi, 1, 1.0), (1.0 - yi, 1, -1.0)):
            push = ri + margin - val
            if push > 0:
                disp[i, axis] += sign * push
        for j in range(n):
            if i == j:
                continue
            dx = xi - centers[j, 0]
            dy = yi - centers[j, 1]
            d = np.hypot(dx, dy)
            if d < 1e-12:
                dx, dy = 1e-6, 0.0
                d = 1e-6
            overlap = ri + radii[j] + margin - d
            if overlap > 0:
                disp[i, 0] += overlap * dx / d
                disp[i, 1] += overlap * dy / d
    new = centers + step * disp
    new = np.clip(new, 0.0, 1.0)
    return new


def _validate(sol):
    n = len(sol)
    for i in range(n):
        x, y, r = sol[i]
        if r <= 0:
            return False
        if x - r < -1e-12 or x + r > 1 + 1e-12:
            return False
        if y - r < -1e-12 or y + r > 1 + 1e-12:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(sol[i, 0] - sol[j, 0], sol[i, 1] - sol[j, 1])
            if d < sol[i, 2] + sol[j, 2] - 1e-12:
                return False
    return True


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.0  # margin

    centers = _hex_init(32)

    best_sum = -1.0
    best_centers = None
    best_radii = None

    while time.process_time() - t0 < deadline:
        radii = _solve_lp(centers)
        if radii is None:
            break
        s = radii.sum()
        if s > best_sum:
            best_sum = s
            best_centers = centers.copy()
            best_radii = radii.copy()
        centers = _relax(centers, radii)
        if time.process_time() - t0 >= deadline:
            break

    if best_centers is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.array([[0.5, 0.5, 0.001]] * 32)

    sol = np.column_stack([best_centers, best_radii])
    # shrink radii slightly for safety
    sol[:, 2] = np.maximum(sol[:, 2] - 1e-9, 1e-9)
    # re-clip centers so circles stay inside
    for i in range(len(sol)):
        x, y, r = sol[i]
        x = min(max(x, r), 1.0 - r)
        y = min(max(y, r), 1.0 - r)
        sol[i, 0] = x
        sol[i, 1] = y
    if _validate(sol):
        return sol
    if start is not None:
        return np.asarray(start, dtype=float)
    return sol

import numpy as np
import time
from scipy.optimize import minimize


def _hex_init(n=32):
    # 6x6 triangular lattice, spacing 1/6 horizontally, sqrt(3)/6 vertically
    hx = 1.0 / 6.0
    hy = np.sqrt(3.0) / 6.0
    pts = []
    for row in range(6):
        for col in range(6):
            x = (col + 0.5 * (row % 2)) * hx
            y = row * hy
            pts.append((x, y))
    pts = pts[:n]
    pts = np.array(pts, dtype=float)
    # scale/translate into [0.05, 0.95]^2
    xmin, xmax = pts[:, 0].min(), pts[:, 0].max()
    ymin, ymax = pts[:, 1].min(), pts[:, 1].max()
    sx = (0.95 - 0.05) / max(xmax - xmin, 1e-12)
    sy = (0.95 - 0.05) / max(ymax - ymin, 1e-12)
    s = min(sx, sy)
    pts[:, 0] = 0.05 + (pts[:, 0] - xmin) * s
    pts[:, 1] = 0.05 + (pts[:, 1] - ymin) * s
    return pts


def _initial_radii(pts):
    n = len(pts)
    r = np.empty(n)
    for i in range(n):
        x, y = pts[i]
        wall = min(x, 1.0 - x, y, 1.0 - y)
        dmin = np.inf
        for j in range(n):
            if j == i:
                continue
            d = np.hypot(pts[i, 0] - pts[j, 0], pts[i, 1] - pts[j, 1])
            if d < dmin:
                dmin = d
        r[i] = 0.9 * min(wall, 0.5 * dmin)
    return np.maximum(r, 1e-6)


def _unpack(z, n):
    z = z.reshape(n, 3)
    return z[:, 0], z[:, 1], z[:, 2]


def _objective(z, n):
    return -np.sum(z.reshape(n, 3)[:, 2])


def _make_constraints(n):
    cons = []
    # wall constraints
    def wall_xlo(z, n=n):
        x, y, r = _unpack(z, n)
        return x - r

    def wall_xhi(z, n=n):
        x, y, r = _unpack(z, n)
        return 1.0 - x - r

    def wall_ylo(z, n=n):
        x, y, r = _unpack(z, n)
        return y - r

    def wall_yhi(z, n=n):
        x, y, r = _unpack(z, n)
        return 1.0 - y - r

    cons.append({'type': 'ineq', 'fun': wall_xlo})
    cons.append({'type': 'ineq', 'fun': wall_xhi})
    cons.append({'type': 'ineq', 'fun': wall_ylo})
    cons.append({'type': 'ineq', 'fun': wall_yhi})

    # pairwise constraints
    pairs = [(i, j) for i in range(n) for j in range(i + 1, n)]

    def pair_con(z, n=n, pairs=pairs):
        x, y, r = _unpack(z, n)
        out = np.empty(len(pairs))
        for k, (i, j) in enumerate(pairs):
            dx = x[i] - x[j]
            dy = y[i] - y[j]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        return out

    cons.append({'type': 'ineq', 'fun': pair_con})
    return cons


def _feasible(z, n, tol=1e-7):
    x, y, r = _unpack(z, n)
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(1 - x - r < -tol):
        return False
    if np.any(y - r < -tol) or np.any(1 - y - r < -tol):
        return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            if d < r[i] + r[j] - tol:
                return False
    return True


def _shrink(arr, eps=1e-9):
    arr = np.array(arr, dtype=float, copy=True)
    arr[:, 2] = np.maximum(arr[:, 2] - eps, 1e-12)
    return arr


def construct(budget_seconds, start):
    n = 32
    t0 = time.process_time()
    deadline = t0 + max(budget_seconds - 1.5, 0.5)

    best = None
    best_score = -np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (n, 3):
            best = s.copy()
            best_score = float(np.sum(s[:, 2]))

    pts = _hex_init(n)
    r0 = _initial_radii(pts)
    z0 = np.concatenate([pts[:, 0], pts[:, 1], r0])

    bounds = [(0.0, 1.0)] * (2 * n) + [(1e-6, 0.5)] * n
    cons = _make_constraints(n)

    state = {'stop': False}

    def callback(z):
        if time.process_time() > deadline:
            state['stop'] = True
            raise StopIteration

    try:
        res = minimize(
            _objective, z0, args=(n,), method='SLSQP',
            bounds=bounds, constraints=cons,
            options={'maxiter': 1000, 'ftol': 1e-10},
            callback=callback,
        )
        z = res.x
        if _feasible(z, n):
            score = float(np.sum(z.reshape(n, 3)[:, 2]))
            if score > best_score:
                best = z.reshape(n, 3).copy()
                best_score = score
    except StopIteration:
        pass
    except Exception:
        pass

    if best is None:
        # fallback: shrink start or build a tiny valid config
        if start is not None:
            return _shrink(np.asarray(start, dtype=float))
        return _shrink(np.column_stack([pts, r0]))

    return _shrink(best)

import numpy as np
import time
from scipy.optimize import minimize


def _pack_vars(z):
    return z.reshape(-1, 3)


def _objective(z):
    return -np.sum(z[2::3])


def _constraints(z, n):
    x = z[0::3]; y = z[1::3]; r = z[2::3]
    cons = []
    # walls
    cons.append(x - r)          # >= 0
    cons.append(1.0 - x - r)    # >= 0
    cons.append(y - r)
    cons.append(1.0 - y - r)
    # pairwise
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            cons.append(np.sqrt(dx*dx + dy*dy) - r[i] - r[j])
    return np.array(cons)


def _polish(z0, n, deadline):
    cons = {'type': 'ineq', 'fun': lambda z: _constraints(z, n)}
    bounds = [(0.0, 1.0)] * (2 * n) + [(1e-6, 0.5)] * n
    best = z0.copy()
    bestval = _objective(z0)
    # try a few restarts / methods within time
    attempts = 0
    while time.process_time() < deadline and attempts < 6:
        attempts += 1
        try:
            res = minimize(_objective, best, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': 500, 'ftol': 1e-12})
            if res.fun < bestval and np.all(_constraints(res.x, n) >= -1e-9):
                best = res.x.copy()
                bestval = res.fun
        except Exception:
            break
        if time.process_time() >= deadline:
            break
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = min(t0 + budget_seconds - 1.5, t0 + 8.5)
    n = 32

    # Greedy farthest-point insertion
    rng = np.random.RandomState(12345)
    grid = np.linspace(0.0, 1.0, 25)
    gx, gy = np.meshgrid(grid, grid)
    cand = np.column_stack([gx.ravel(), gy.ravel()])
    rnd = rng.rand(200, 2)
    cand = np.vstack([cand, rnd])

    centers = []
    radii = []
    for k in range(n):
        best_r = -1.0
        best_c = None
        for c in cand:
            x, y = c
            r = min(x, 1.0 - x, y, 1.0 - y)
            if r <= 0:
                continue
            for (cx, cy), cr in zip(centers, radii):
                d = np.hypot(x - cx, y - cy) - cr
                if d < r:
                    r = d
            if r > best_r:
                best_r = r
                best_c = (x, y)
        centers.append(best_c)
        radii.append(max(best_r, 1e-6))

    z0 = np.zeros(3 * n)
    for i, ((x, y), r) in enumerate(zip(centers, radii)):
        z0[3*i] = x; z0[3*i+1] = y; z0[3*i+2] = r

    z = _polish(z0, n, deadline)

    sol = _pack_vars(z).copy()
    # shrink radii slightly for safety
    sol[:, 2] = np.maximum(sol[:, 2] - 1e-9, 1e-9)

    # verify feasibility
    x = sol[:, 0]; y = sol[:, 1]; r = sol[:, 2]
    ok = np.all(r > 0) and np.all(x - r >= -1e-12) and np.all(x + r <= 1 + 1e-12) \
         and np.all(y - r >= -1e-12) and np.all(y + r <= 1 + 1e-12)
    if ok:
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i]-x[j], y[i]-y[j])
                if d < r[i] + r[j] - 1e-12:
                    ok = False
                    break
            if not ok:
                break

    score_new = np.sum(sol[:, 2]) if ok else -1.0

    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        s[:, 2] = np.maximum(s[:, 2] - 1e-9, 1e-9)
        score_old = np.sum(s[:, 2])
        if score_old >= score_new:
            return s
    return sol

import numpy as np
import time
from scipy.optimize import linprog


def _hex_init(n=32, rows=6):
    pts = []
    for j in range(rows):
        y = (j + 0.5) / rows
        cols = 6 if j % 2 == 0 else 5
        for i in range(cols):
            x = (i + 0.5) / cols
            if j % 2 == 1:
                x = (i + 1.0) / (cols + 1)
            pts.append((x, y))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    return np.array(pts, dtype=float)


def _solve_lp(centers):
    n = len(centers)
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        x, y = centers[i]
        for bound in (x, 1.0 - x, y, 1.0 - y):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(bound)
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                  bounds=[(0, None)] * n, method='highs')
    if not res.success:
        return None
    return res.x


def _relax(centers, radii, step=0.05, margin=0.0):
    n = len(centers)
    disp = np.zeros_like(centers)
    for i in range(n):
        xi, yi = centers[i]
        ri = radii[i]
        for (val, axis, sign) in ((xi, 0, 1.0), (1.0 - xi, 0, -1.0),
                                  (yi, 1, 1.0), (1.0 - yi, 1, -1.0)):
            push = ri + margin - val
            if push > 0:
                disp[i, axis] += sign * push
        for j in range(n):
            if i == j:
                continue
            dx = xi - centers[j, 0]
            dy = yi - centers[j, 1]
            d = np.hypot(dx, dy)
            if d < 1e-12:
                dx, dy = 1e-6, 0.0
                d = 1e-6
            overlap = ri + radii[j] + margin - d
            if overlap > 0:
                disp[i, 0] += overlap * dx / d
                disp[i, 1] += overlap * dy / d
    new = centers + step * disp
    return np.clip(new, 1e-6, 1.0 - 1e-6)


def _validate(sol):
    n = len(sol)
    for i in range(n):
        x, y, r = sol[i]
        if r <= 0:
            return False
        if x - r < -1e-12 or x + r > 1 + 1e-12:
            return False
        if y - r < -1e-12 or y + r > 1 + 1e-12:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(sol[i, 0] - sol[j, 0], sol[i, 1] - sol[j, 1])
            if d < sol[i, 2] + sol[j, 2] - 1e-12:
                return False
    return True


def _finalize(centers, radii):
    sol = np.column_stack([centers, radii])
    sol[:, 2] = np.maximum(sol[:, 2] - 1e-9, 1e-9)
    for i in range(len(sol)):
        x, y, r = sol[i]
        sol[i, 0] = min(max(x, r), 1.0 - r)
        sol[i, 1] = min(max(y, r), 1.0 - r)
    return sol


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.0
    n = 32

    best_sum = -1.0
    best_centers = None
    best_radii = None

    seeds = []
    if start is not None:
        S = np.asarray(start, dtype=float)
        if S.shape == (n, 3) and np.all(S[:, 2] > 0):
            seeds.append(S[:, :2].copy())
    rng = np.random.default_rng(99)
    for rows in (6, 7, 5, 8):
        seeds.append(_hex_init(n, rows))
    for _ in range(6):
        c = rng.random((n, 2))
        seeds.append(c)

    # Phase 1: LP + relax from each seed, then keep the best
    idx = 0
    while time.process_time() - t0 < deadline * 0.6:
        if idx < len(seeds):
            centers = seeds[idx].copy()
            idx += 1
        else:
            # perturb best
            centers = best_centers + rng.normal(0, 0.01, best_centers.shape)
            centers = np.clip(centers, 1e-6, 1 - 1e-6)
            idx += 1

        local_best = -1.0
        local_c = None
        local_r = None
        for _ in range(60):
            if time.process_time() - t0 >= deadline * 0.6:
                break
            radii = _solve_lp(centers)
            if radii is None:
                break
            s = radii.sum()
            if s > local_best:
                local_best = s
                local_c = centers.copy()
                local_r = radii.copy()
            centers = _relax(centers, radii, step=0.05)
        if local_best > best_sum:
            best_sum = local_best
            best_centers = local_c
            best_radii = local_r

    if best_centers is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        best_centers = _hex_init(n)
        best_radii = _solve_lp(best_centers)

    # Phase 2: fine-tune from best with smaller steps
    centers = best_centers.copy()
    radii = best_radii.copy()
    step = 0.02
    stall = 0
    while time.process_time() - t0 < deadline:
        radii = _solve_lp(centers)
        if radii is None:
            break
        s = radii.sum()
        if s > best_sum:
            best_sum = s
            best_centers = centers.copy()
            best_radii = radii.copy()
            stall = 0
        else:
            stall += 1
        centers = _relax(centers, radii, step=step)
        if stall > 20:
            centers = best_centers + rng.normal(0, 0.005, best_centers.shape)
            centers = np.clip(centers, 1e-6, 1 - 1e-6)
            stall = 0
            step = 0.02

    sol = _finalize(best_centers, best_radii)
    if not _validate(sol):
        if start is not None:
            return np.asarray(start, dtype=float)
        sol[:, 2] = np.maximum(sol[:, 2] * 0.99, 1e-9)
    return sol

import numpy as np
import time
from scipy.optimize import linprog


def _initial_centers(n, seed):
    rng = np.random.RandomState(seed)
    rows = 6
    pts = []
    for j in range(rows):
        y = (j + 0.5) / rows
        cols = 6 if j % 2 == 0 else 5
        for i in range(cols):
            x = (i + 0.5) / cols
            if j % 2 == 1:
                x = (i + 1.0) / (cols + 1)
            pts.append((x + rng.randn() * 0.01, y + rng.randn() * 0.01))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((rng.rand(), rng.rand()))
    return np.clip(np.array(pts, dtype=float), 0.02, 0.98)


def _solve_lp(centers):
    n = len(centers)
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        x, y = centers[i]
        for bound in (x, 1.0 - x, y, 1.0 - y):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(bound)
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    bounds = [(0, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
    except Exception:
        return None
    if not res.success:
        return None
    return res.x


def _net_force(centers, radii, margin):
    """Compute forces pushing centers apart to increase radii."""
    n = len(centers)
    disp = np.zeros_like(centers)
    for i in range(n):
        xi, yi = centers[i]
        ri = radii[i]
        # walls: if circle touches wall (ri near wall distance), push toward center
        for val, axis, sign in ((xi, 0, 1.0), (1.0 - xi, 0, -1.0),
                                (yi, 1, 1.0), (1.0 - yi, 1, -1.0)):
            push = ri + margin - val
            if push > 0:
                disp[i, axis] += sign * push
        for j in range(n):
            if i == j:
                continue
            dx = xi - centers[j, 0]
            dy = yi - centers[j, 1]
            d = np.hypot(dx, dy)
            if d < 1e-12:
                dx, dy = 1e-6, 0.0
                d = 1e-6
            # if touching (gap near 0), push apart
            gap = d - (ri + radii[j])
            if gap < margin:
                overlap = margin - gap
                disp[i, 0] += overlap * dx / d
                disp[i, 1] += overlap * dy / d
    return disp


def _relax(centers, radii, step, margin):
    disp = _net_force(centers, radii, margin)
    new = centers + step * disp
    return np.clip(new, 0.0, 1.0)


def _validate(sol):
    n = len(sol)
    for i in range(n):
        x, y, r = sol[i]
        if r <= 0:
            return False
        if x - r < -1e-12 or x + r > 1 + 1e-12:
            return False
        if y - r < -1e-12 or y + r > 1 + 1e-12:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(sol[i, 0] - sol[j, 0], sol[i, 1] - sol[j, 1])
            if d < sol[i, 2] + sol[j, 2] - 1e-12:
                return False
    return True


def _polish(sol, deadline, t0):
    """Local optimization: small random perturbations of centers, re-solve LP."""
    n = len(sol)
    best = sol.copy()
    best_sum = sol[:, 2].sum()
    centers = sol[:, :2].copy()
    rng = np.random.RandomState(999)
    scale = 0.01
    while time.process_time() - t0 < deadline:
        trial = centers + rng.randn(n, 2) * scale
        trial = np.clip(trial, 0.0, 1.0)
        radii = _solve_lp(trial)
        if radii is None:
            continue
        s = radii.sum()
        if s > best_sum:
            best_sum = s
            best = np.column_stack([trial, radii])
            centers = trial.copy()
            scale = max(scale * 0.95, 1e-4)
        else:
            scale = min(scale * 1.02, 0.03)
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 0.8

    n = 32
    best_sol = None
    best_sum = -1.0

    # seed with start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (n, 3):
            best_sol = s.copy()
            best_sum = s[:, 2].sum()

    seeds = [0, 1, 2, 3, 4, 5, 6, 7]
    for seed in seeds:
        if time.process_time() - t0 >= deadline:
            break
        centers = _initial_centers(n, seed)
        # alternate LP and relaxation
        local_best = None
        local_best_sum = -1.0
        for it in range(40):
            if time.process_time() - t0 >= deadline:
                break
            radii = _solve_lp(centers)
            if radii is None:
                break
            s = radii.sum()
            if s > local_best_sum:
                local_best_sum = s
                local_best = np.column_stack([centers, radii])
            step = 0.03 * (1.0 - it / 40.0) + 0.005
            margin = 0.001
            centers = _relax(centers, radii, step, margin)
        if local_best is not None and local_best_sum > best_sum:
            best_sum = local_best_sum
            best_sol = local_best

    if best_sol is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.array([[0.5, 0.5, 0.001]] * n)

    # polish
    polished = _polish(best_sol, deadline, t0)
    if polished[:, 2].sum() > best_sum:
        best_sol = polished

    sol = best_sol.copy()
    # safety: shrink radii
    sol[:, 2] = np.maximum(sol[:, 2] - 1e-8, 1e-9)
    for i in range(n):
        x, y, r = sol[i]
        x = min(max(x, r), 1.0 - r)
        y = min(max(y, r), 1.0 - r)
        sol[i, 0] = x
        sol[i, 1] = y
    # extra iterative shrink to guarantee feasibility
    for _ in range(20):
        ok = True
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(sol[i, 0] - sol[j, 0], sol[i, 1] - sol[j, 1])
                need = sol[i, 2] + sol[j, 2]
                if d < need:
                    over = need - d
                    sol[i, 2] = max(sol[i, 2] - over * 0.5 - 1e-12, 1e-9)
                    sol[j, 2] = max(sol[j, 2] - over * 0.5 - 1e-12, 1e-9)
                    ok = False
        if ok:
            break
    if _validate(sol):
        return sol
    if start is not None:
        return np.asarray(start, dtype=float)
    return sol

import numpy as np
import time
from scipy.optimize import linprog


def _hex_init(n=32):
    pts = []
    rows = 6
    for j in range(rows):
        y = (j + 0.5) / rows
        cols = 6 if j % 2 == 0 else 5
        for i in range(cols):
            x = (i + 0.5) / cols
            if j % 2 == 1:
                x = (i + 1.0) / (cols + 1)
            pts.append((x, y))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    return np.array(pts, dtype=float)


def _solve_lp(centers):
    n = len(centers)
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        x, y = centers[i]
        for bound in (x, 1.0 - x, y, 1.0 - y):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(bound)
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    bounds = [(0, None)] * n
    res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                  bounds=bounds, method='highs')
    if not res.success:
        return None
    return res.x


def _relax(centers, radii, step=0.02, margin=0.0):
    n = len(centers)
    disp = np.zeros_like(centers)
    for i in range(n):
        xi, yi = centers[i]
        ri = radii[i]
        for (val, axis, sign) in ((xi, 0, 1.0), (1.0 - xi, 0, -1.0),
                                  (yi, 1, 1.0), (1.0 - yi, 1, -1.0)):
            push = ri + margin - val
            if push > 0:
                disp[i, axis] += sign * push
        for j in range(n):
            if i == j:
                continue
            dx = xi - centers[j, 0]
            dy = yi - centers[j, 1]
            d = np.hypot(dx, dy)
            if d < 1e-12:
                dx, dy = 1e-6, 0.0
                d = 1e-6
            overlap = ri + radii[j] + margin - d
            if overlap > 0:
                disp[i, 0] += overlap * dx / d
                disp[i, 1] += overlap * dy / d
    new = centers + step * disp
    new = np.clip(new, 0.0, 1.0)
    return new


def _validate(sol):
    n = len(sol)
    for i in range(n):
        x, y, r = sol[i]
        if r <= 0:
            return False
        if x - r < -1e-12 or x + r > 1 + 1e-12:
            return False
        if y - r < -1e-12 or y + r > 1 + 1e-12:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(sol[i, 0] - sol[j, 0], sol[i, 1] - sol[j, 1])
            if d < sol[i, 2] + sol[j, 2] - 1e-12:
                return False
    return True


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 0.5

    if start is not None:
        s = np.asarray(start, dtype=float)
        centers = np.clip(s[:, :2].copy(), 0.0, 1.0)
    else:
        centers = _hex_init(32)

    best_sum = -1.0
    best_centers = None
    best_radii = None

    step = 0.05
    prev_score = -np.inf

    while time.process_time() - t0 < deadline:
        radii = _solve_lp(centers)
        if radii is None:
            break
        s = radii.sum()
        if s > best_sum:
            best_sum = s
            best_centers = centers.copy()
            best_radii = radii.copy()
        if s > prev_score:
            pass
        else:
            step = max(step * 0.7, 1e-4)
        prev_score = s
        centers = _relax(centers, radii, step=step, margin=0.0)
        if time.process_time() - t0 >= deadline:
            break

    if best_centers is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.array([[0.5, 0.5, 0.001]] * 32)

    sol = np.column_stack([best_centers, best_radii])
    sol[:, 2] = np.maximum(sol[:, 2] - 1e-9, 1e-9)
    for i in range(len(sol)):
        x, y, r = sol[i]
        x = min(max(x, r), 1.0 - r)
        y = min(max(y, r), 1.0 - r)
        sol[i, 0] = x
        sol[i, 1] = y
    if _validate(sol):
        return sol
    if start is not None:
        return np.asarray(start, dtype=float)
    return sol
